import React, { useState } from 'react';
import StepOne from './component/Navbar';
import StepTwo from './component/StepTwo';
import StepThree from './component/StepThree';

function App() {
  const [step, setStep] = useState(1);

  return (
    <div className="container mt-5">
      <div className="card p-4 shadow-sm" style={{ maxWidth: '500px', margin: '0 auto' }}>
        {step === 1 && <StepOne next={() => setStep(2)} />}
        {step === 2 && <StepTwo next={() => setStep(3)} prev={() => setStep(1)} />}
        {step === 3 && <StepThree prev={() => setStep(2)} />}
      </div>
    </div>
  );
}

export default App;
